1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerTelephoneException;
7	
8	/**
9	 * Rejects a new owner whose E.164 telephone is already used by any other owner.
10	 * Runs after {@link NormalizeOwnerTelephone} (so {@code owner} holds the E.164
11	 * telephone) and before {@link SaveOwner}: if any existing owner has the same
12	 * E.164 telephone, it throws a checked {@link DuplicateOwnerTelephoneException},
13	 * which the escalation handler turns into a 409 Conflict.
14	 */
15	public class RejectDuplicateOwnerTelephone {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
18	            throws DuplicateOwnerTelephoneException {
19	        String telephone = E164Telephone.toE164OrNull(owner.getTelephone());
20	        if (telephone == null) {
21	            return; // not a valid E.164 number; nothing to compare against
22	        }
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
25	                continue; // never conflict with the owner itself
26	            }
27	            if (telephone.equals(E164Telephone.toE164OrNull(existing.getTelephone()))) {
28	                throw new DuplicateOwnerTelephoneException(
29	                        "Telephone is already used by another owner");
30	            }
31	        }
32	    }
33	}
